# winpass tab completion for PowerShell (Constrained Language Mode compatible).
# Add this block to your $PROFILE. Generated by: winpass completion powershell
Register-ArgumentCompleter -Native -CommandName winpass, winpass.exe -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    $subcommands = 'show', 'insert', 'generate', 'rm', 'mv', 'cp', 'ls', 'find', 'export', 'import', 'help', 'version', 'completion'
    $entrySubcommands = 'show', 'insert', 'generate', 'rm', 'mv', 'cp', 'ls', 'remove', 'rename', 'copy', 'list'

    # String interpolation avoids method calls, which CLM restricts on non-core types
    $elements = @($commandAst.CommandElements | ForEach-Object { "$_" })

    # 1-based position of the argument being completed (the command itself is element 0)
    $position = $elements.Count - 1
    if ($wordToComplete -eq '') { $position = $elements.Count }

    $candidates = @()
    if ($position -le 1) {
        # A bare entry name acts as 'show', so offer both subcommands and entries
        $candidates = @($subcommands) + @(& winpass.exe __complete $wordToComplete)
    }
    elseif ($entrySubcommands -contains $elements[1] -and $wordToComplete -notlike '-*') {
        $candidates = @(& winpass.exe __complete $wordToComplete)
    }
    elseif ($elements[1] -eq 'completion' -and $position -eq 2) {
        $candidates = @('powershell')
    }

    $candidates | Where-Object { $_ -like "$wordToComplete*" } | ForEach-Object {
        if ($_ -match '\s') { "'$_'" } else { $_ }
    }
}
